class LoadError extends StatelessWidget {
  final bool loading; final String? error; final VoidCallback onRetry; const LoadError({super.key,required this.loading,required this.error,required this.onRetry});
  @override Widget build(BuildContext context) { if(loading) return const Padding(padding:EdgeInsets.all(28),child: Center(child:CircularProgressIndicator())); if(error!=null) return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.info_outline,color:forestGreen,size:30),const SizedBox(height:8),Text(error!,style:const TextStyle(color:mutedText)),const SizedBox(height:10),OutlinedButton.icon(onPressed:onRetry,icon:const Icon(Icons.refresh),label:const Text('Retry'))]))); return const SizedBox.shrink(); }
}
class Panel extends StatelessWidget { final Widget child; const Panel({super.key,required this.child}); @override Widget build(BuildContext context)=>Card(color:Colors.white,elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18),side:const BorderSide(color:Color(0xFFE5EAE2))),child:Padding(padding:const EdgeInsets.all(16),child:child)); }
class WeatherHero extends StatelessWidget { final Map<String,dynamic>? weather; const WeatherHero({super.key,required this.weather}); @override Widget build(BuildContext context){final temp=nested(weather,['current','data','temperature_2m','value']);final hum=nested(weather,['current','data','relative_humidity_2m','value']);final wind=nested(weather,['current','data','wind_speed_10m','value']);final time=nested(weather,['current','time']);return Container(width:double.infinity,padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:forestGreen,borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Row(children:[Icon(Icons.cloud_outlined,color:Colors.white,size:26),SizedBox(width:9),Text('Field weather',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:18))]),const SizedBox(height:12),Text(temp is num?'${temp.toStringAsFixed(1)} °C':'Weather unavailable',style:const TextStyle(color:Colors.white,fontSize:34,fontWeight:FontWeight.bold)),const SizedBox(height:8),Wrap(spacing:18,runSpacing:8,children:[WeatherBit(icon:Icons.water_drop_outlined,label:'Humidity ${fmt(hum,suffix:'%')}'),WeatherBit(icon:Icons.air,label:'Wind ${fmt(wind,suffix:' km/h')}')]),if(time!=null) Padding(padding:const EdgeInsets.only(top:8),child:Text('Weather time: $time',style:const TextStyle(color:Colors.white70,fontSize:11))),if(weather==null) const Padding(padding:EdgeInsets.only(top:8),child:Text('No live weather response available.',style:TextStyle(color:Colors.white70))) ]));} }
class WeatherBit extends StatelessWidget { final IconData icon; final String label; const WeatherBit({super.key,required this.icon,required this.label}); @override Widget build(BuildContext context)=>Row(mainAxisSize:MainAxisSize.min,children:[Icon(icon,color:Colors.white70,size:18),const SizedBox(width:5),Text(label,style:const TextStyle(color:Colors.white))]); }
class MetricCard extends StatelessWidget {
  final IconData icon;
  final String title, value, note;
  final Color color;
  const MetricCard({super.key, required this.icon, required this.title, required this.value, required this.note, required this.color});
  @override
  Widget build(BuildContext context) => Container(
    padding: const EdgeInsets.all(13),
    decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(16), border: Border.all(color: const Color(0xFFE5EAE2))),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisAlignment: MainAxisAlignment.center, children: [
      Icon(icon, color: color, size: 25), const SizedBox(height: 8),
      Text(title, style: const TextStyle(color: mutedText, fontSize: 12)), const SizedBox(height: 3),
      FittedBox(fit: BoxFit.scaleDown, alignment: Alignment.centerLeft, child: Text(value, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold, color: forestGreen))),
      const SizedBox(height: 3), Text(note, style: const TextStyle(color: mutedText, fontSize: 10), maxLines: 2, overflow: TextOverflow.ellipsis),
    ]),
  );
}
class IrrigationCard extends StatelessWidget {final Map<String,dynamic>? data;const IrrigationCard({super.key,required this.data});@override Widget build(BuildContext context){final status='${data?['advisory']??'UNAVAILABLE'}';final msg='${data?['message']??'No irrigation recommendation available.'}';final reasons=data?['reasons'];final warnings=data?['warnings'];return Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Row(children:[Icon(Icons.water_outlined,color:forestGreen),SizedBox(width:8),Text('Irrigation recommendation',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold,color:forestGreen))]),const SizedBox(height:10),Container(padding:const EdgeInsets.symmetric(horizontal:12,vertical:7),decoration:BoxDecoration(color:status=='IRRIGATION_REVIEW'?const Color(0xFFFFF0D8):status=='INSUFFICIENT_DATA'?const Color(0xFFFFE8E8):const Color(0xFFE5F2E8),borderRadius:BorderRadius.circular(30)),child:Text(status.replaceAll('_',' '),style:const TextStyle(fontWeight:FontWeight.bold))),const SizedBox(height:9),Text(msg),if(reasons is List && reasons.isNotEmpty) ...[const SizedBox(height:10),const Text('Decision factors',style:TextStyle(fontWeight:FontWeight.bold)),...reasons.whereType<Map>().map((r)=>Padding(padding:const EdgeInsets.only(top:5),child:Text('• ${r['factor']}: ${r['value']??'Unavailable'}${r['unit']==null?'':' ${r['unit']}'}${r['growth_stage']==null?'':' (${r['growth_stage']})'}',style:const TextStyle(color:mutedText,fontSize:13))))],if(warnings is List && warnings.isNotEmpty) ...[const SizedBox(height:8),...warnings.map((w)=>Text('⚠ $w',style:const TextStyle(color:Color(0xFF9A5A00),fontSize:12)))],if(data?['decision_basis']!=null) Padding(padding:const EdgeInsets.only(top:10),child:Text('${data!['decision_basis']}',style:const TextStyle(fontSize:11,color:mutedText))) ]));}}
